"""Bounded HTTP ranges for unreliable links; persistent parts and SHA-256 QA."""
import hashlib
import os
import re
import shutil
import time
from concurrent.futures import ThreadPoolExecutor, as_completed
from pathlib import Path
from threading import Event, Lock

import httpx
from filelock import FileLock, Timeout

CHUNK_SIZE=1024*1024
ATTEMPTS=5


class DownloadError(ValueError):
    """Safe, user-facing messages generated by this downloader."""


def sha256(path):
    digest=hashlib.sha256()
    with path.open('rb') as stream:
        for block in iter(lambda:stream.read(1024*1024),b''): digest.update(block)
    return digest.hexdigest()


def range_file(url,destination,size,expected_hash,token,progress,workers=8,stop=None):
    """Retain completed ranges on errors; never publish an unverified file.

    The Hub URL pins a commit; part identity also pins SHA-256 and chunk size.
    HTTPX drops authorization on cross-origin redirects to the signed CDN URL.
    """
    destination=Path(destination)
    if not re.fullmatch('[0-9a-f]{64}',expected_hash) or size<=0:
        raise DownloadError('모델 SHA-256 또는 크기 확인 실패')
    destination.parent.mkdir(parents=True,exist_ok=True)
    lock=FileLock(str(destination)+'.lock')
    try: lock.acquire(timeout=1)
    except Timeout:
        raise DownloadError('다른 프로세스에서 같은 모델을 다운로드 중입니다. 기존 다운로드 종료 후 다시 시도하세요.') from None
    try:
        _range_file(url,destination,size,expected_hash,token,progress,workers,stop or Event())
    finally: lock.release()


def _range_file(url,destination,size,expected_hash,token,progress,workers,stop):
    if destination.is_file() and destination.stat().st_size==size and sha256(destination)==expected_hash:
        progress(size,0)
        return
    parts=destination.parent/(destination.name+'.parts')/f'{expected_hash}-{CHUNK_SIZE}'
    parts.mkdir(parents=True,exist_ok=True)
    ranges=[(start,min(size,start+CHUNK_SIZE)) for start in range(0,size,CHUNK_SIZE)]
    pending=[]; completed=0; transferred=0; guard=Lock()
    for start,end in ranges:
        part=parts/f'{start}.part'
        if part.is_file() and part.stat().st_size==end-start: completed+=end-start
        else: pending.append((start,end))
    progress(completed,0)
    headers={'Accept-Encoding':'identity'}
    if token: headers['Authorization']='Bearer '+token
    with httpx.Client(follow_redirects=True,timeout=httpx.Timeout(20,connect=10),
                      limits=httpx.Limits(max_connections=workers,max_keepalive_connections=workers)) as client:
        def fetch(bounds):
            nonlocal completed,transferred
            start,end=bounds
            temporary=parts/f'{start}.tmp'
            data=bytearray(temporary.read_bytes()) if temporary.is_file() else bytearray()
            if len(data)>end-start:
                temporary.unlink(); data.clear()
            if len(data)==end-start:
                temporary.replace(parts/f'{start}.part')
                with guard:
                    completed+=len(data); progress(completed,transferred)
                return
            for attempt in range(ATTEMPTS):
                if stop.is_set(): raise DownloadError('다운로드 중단 · 완료한 구간은 다음 시도에 재사용됩니다.')
                if len(data)==end-start:
                    temporary.replace(parts/f'{start}.part')
                    with guard:
                        completed+=len(data); progress(completed,transferred)
                    return
                try:
                    began=time.monotonic(); offset=start+len(data)
                    with client.stream('GET',url,headers={**headers,'Range':f'bytes={offset}-{end-1}'}) as response:
                        response.raise_for_status()
                        if response.status_code!=206 or response.headers.get('Content-Range')!=f'bytes {offset}-{end-1}/{size}':
                            raise DownloadError('서버가 요청한 파일 구간을 반환하지 않았습니다.')
                        for block in response.iter_bytes(64*1024):
                            if stop.is_set(): raise DownloadError('다운로드 중단 · 완료한 구간은 다음 시도에 재사용됩니다.')
                            if time.monotonic()-began>60: raise httpx.ReadTimeout('range deadline exceeded')
                            data.extend(block)
                            if len(data)>end-start: raise DownloadError('다운로드 구간 크기 불일치')
                            with temporary.open('ab') as output: output.write(block)
                            with guard:
                                transferred+=len(block)
                                progress(completed,transferred)
                        if len(data)!=end-start: raise httpx.RemoteProtocolError('incomplete range')
                    temporary.replace(parts/f'{start}.part')
                    with guard:
                        completed+=len(data)
                        progress(completed,transferred)
                    return
                except (httpx.TransportError,httpx.HTTPStatusError) as error:
                    status=getattr(getattr(error,'response',None),'status_code',None)
                    if status is not None and status not in (408,429,500,502,503,504): raise
                    if attempt==ATTEMPTS-1: raise
                    if stop.wait(min(8,2**attempt)): raise DownloadError('다운로드 중단 · 완료한 구간은 보존됩니다.') from None
        with ThreadPoolExecutor(max_workers=workers) as pool:
            futures=[pool.submit(fetch,bounds) for bounds in pending]
            try:
                for future in as_completed(futures): future.result()
            except BaseException:
                stop.set()
                for future in futures: future.cancel()
                raise
    if stop.is_set(): raise DownloadError('다운로드 중단 · 완료한 구간은 보존됩니다.')
    assembly=destination.with_name(destination.name+'.assembling')
    digest=hashlib.sha256()
    try:
        with assembly.open('wb') as output:
            for start,end in ranges:
                data=(parts/f'{start}.part').read_bytes()
                if len(data)!=end-start: raise DownloadError('다운로드 구간 크기 불일치')
                output.write(data); digest.update(data)
            output.flush(); os.fsync(output.fileno())
        if digest.hexdigest()!=expected_hash:
            # Quarantine only this download's corrupt parts, allowing a clean retry.
            parts.rename(parts.with_name(parts.name+f'.invalid-{time.time_ns()}'))
            raise DownloadError('모델 SHA-256 불일치 · 손상 구간을 격리했습니다. 다시 다운로드하세요.')
        assembly.replace(destination)
        # All of these parts now exist in the verified destination.
        for start,_ in ranges: (parts/f'{start}.part').unlink()
        parts.rmdir()
    finally:
        assembly.unlink(missing_ok=True)


def prepare_snapshot(model,revision,plan,root,token,tracker,notify,workers,stop=None):
    from huggingface_hub import hf_hub_download, hf_hub_url, get_hf_file_metadata, try_to_load_from_cache
    folder=Path(root)/revision
    folder.mkdir(parents=True,exist_ok=True)
    completed=0; transferred=0
    for entry in sorted(plan,key=lambda entry:entry.file_size):
        name=entry.filename
        relative=Path(name)
        if relative.is_absolute() or '..' in relative.parts: raise DownloadError('잘못된 모델 파일 경로')
        target=folder/relative
        cached=try_to_load_from_cache(model,name,revision=revision)
        if isinstance(cached,str) and Path(cached).stat().st_size==entry.file_size:
            target.parent.mkdir(parents=True,exist_ok=True)
            if not target.is_file() or target.stat().st_size!=entry.file_size: shutil.copyfile(cached,target)
            completed+=entry.file_size
            tracker.update('completed',completed)
            continue
        if name.endswith('.safetensors'):
            url=hf_hub_url(model,name,revision=revision)
            metadata=get_hf_file_metadata(url,token=token)
            if metadata.size!=entry.file_size or metadata.commit_hash!=revision: raise DownloadError('모델 메타데이터 불일치')
            notify('가중치 구간 다운로드 중 · 완료한 구간은 재시작 후에도 재사용합니다')
            base_completed,base_transferred=completed,transferred
            restored=False
            def report(done,received):
                nonlocal completed,transferred,restored
                completed=base_completed+done; transferred=base_transferred+received
                tracker.update('completed',completed)
                tracker.update('transfer',transferred)
                if not restored:
                    tracker.reset_rate(); restored=True
            range_file(url,target,entry.file_size,metadata.etag,token,report,workers,stop)
        else:
            source=hf_hub_download(model,name,revision=revision,token=token)
            target.parent.mkdir(parents=True,exist_ok=True)
            shutil.copyfile(source,target)
            completed+=entry.file_size
            tracker.update('completed',completed)
    notify('다운로드 파일 조립·검증 완료')
    return folder
